namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile has been set up."),
            CreateNotification("You have 3 unread messages."),
        });
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>
    /// Returns notifications added after the given timestamp.
    /// Simulates a new notification roughly every 10 seconds.
    /// </summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        lock (_lock)
        {
            MaybeGenerateNew();
            return Task.FromResult(
                _notifications.Where(n => n.Timestamp > since).ToList());
        }
    }

    private void MaybeGenerateNew()
    {
        // Generate a new notification ~50 % of the time this is called.
        if (Random.Shared.Next(2) == 0)
        {
            var messages = new[]
            {
                "New comment on your post.",
                "Someone liked your photo.",
                "System maintenance scheduled.",
                "Your report is ready to download.",
                "A new user signed up.",
                "Deployment completed successfully.",
            };

            _notifications.Add(
                CreateNotification(messages[Random.Shared.Next(messages.Length)]));
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? notifications;
    private DateTime lastChecked;
    private CancellationTokenSource? cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            // Restored from prerender state — skip the fetch.
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationService.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }

        lastChecked = notifications.Count > 0
            ? notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Only starts after the component is interactive in the browser —
            // never during the static prerender pass.
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), token);

            var newer = await NotificationService.GetNotificationsSinceAsync(lastChecked);
            if (newer.Count > 0)
            {
                notifications!.AddRange(newer);
                lastChecked = newer.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        cts?.Cancel();
        cts?.Dispose();
    }
}

