+@page "/notifications"
+@rendermode InteractiveServer
+@inject NotificationService NotificationService
+@implements IDisposable
+
+<PageTitle>Notifications</PageTitle>
+
+<h1>
+    Notifications
+    @if (notifications is not null)
+    {
+        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
+    }
+</h1>
+
+@if (notifications is null)
+{
+    <p><em>Loading...</em></p>
+}
+else if (notifications.Count == 0)
+{
+    <p>No notifications yet.</p>
+}
+else
+{
+    <ul class="list-group">
+        @foreach (var n in notifications)
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <span>@n.Message</span>
+                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private List<Notification>? notifications;
+    private DateTime lastChecked;
+    private CancellationTokenSource? cts;
+
+    [PersistentState]
+    public List<Notification>? PersistedNotifications { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        if (PersistedNotifications is not null)
+        {
+            // Restored from prerender state — skip the fetch.
+            notifications = PersistedNotifications;
+        }
+        else
+        {
+            notifications = await NotificationService.GetNotificationsAsync();
+            PersistedNotifications = notifications;
+        }
+
+        lastChecked = notifications.Count > 0
+            ? notifications.Max(n => n.Timestamp)
+            : DateTime.UtcNow;
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            // Only starts after the component is interactive in the browser —
+            // never during the static prerender pass.
+            cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken token)
+    {
+        while (!token.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), token);
+
+            var newer = await NotificationService.GetNotificationsSinceAsync(lastChecked);
+            if (newer.Count > 0)
+            {
+                notifications!.AddRange(newer);
+                lastChecked = newer.Max(n => n.Timestamp);
+                await InvokeAsync(StateHasChanged);
+            }
+        }
+    }
+
+    public void Dispose()
+    {
+        cts?.Cancel();
+        cts?.Dispose();
+    }
+}
+

